pub use crate::crash::CrashDiagnosis;/// 崩溃诊断：在游戏进程非正常退出后，结合崩溃报告、JVM 致命错误日志与实时日志定位原因。/// 具体的规则匹配与模组归因全部由 `crash` 模块完成，这里只负责收集证据文本。/// 返回 `None` 表示既没有崩溃产物、也没有命中任何规则（视为正常退出，不打扰用户）。fn diagnose_crash(    instance_dir: &std::path::Path,    logs_dir: &std::path::Path,    instance_id: &str,    code: Option<i32>,) -> Option<CrashDiagnosis> {    use std::fs;    // ---- 收集崩溃产物 ----    let crash_dir = instance_dir.join("crash-reports");    let crash_report = newest_match(&crash_dir, |n| n.starts_with("crash-") && n.ends_with(".txt"));    let hs_err = newest_match(instance_dir, |n| n.starts_with("hs_err_pid") && n.ends_with(".log"));    // ---- 证据文本：崩溃报告 + JVM 致命错误 + 实时日志尾部 + latest.log ----    let mut buf = String::new();    if let Some(p) = &crash_report {        if let Ok(t) = fs::read(p) {            buf.push_str(&String::from_utf8_lossy(&t));        }    }    if let Some(p) = &hs_err {        if let Ok(t) = fs::read(p) {            buf.push_str(&String::from_utf8_lossy(&t));        }    }    let live_log = logs_dir.join(format!("{}-live.log", instance_id));    if let Ok(t) = fs::read(&live_log) {        buf.push_str(&tail(&String::from_utf8_lossy(&t), 200));    }    let latest_log = instance_dir.join("logs").join("latest.log");    if let Ok(t) = fs::read(&latest_log) {        buf.push_str(&tail(&String::from_utf8_lossy(&t), 300));    }    if buf.trim().is_empty() {        return None;    }    let mut diag = crate::crash::analyze_text(&buf, code);    diag.crash_report = crash_report.map(|p| p.to_string_lossy().to_string());    // 既没有崩溃产物、也没有命中任何规则：视为正常退出    if diag.confidence == 0 && crash_report.is_none() && hs_err.is_none() {        return None;    }    Some(diag)}